    INSERT INTO property_reviews (
    guest_id, property_id, reservation_id, rating, message) 
    VALUES (
    328, 190, 1015655, 4, 'Sigkez amafozuz zidak cirazke giikeak lazup cefumzeb ohefcob vugsi vudavi ahevi awogi tagjowos.');
    INSERT INTO property_reviews (
    guest_id, property_id, reservation_id, rating, message) 
    VALUES (
    340, 769, 1013720, 5, 'Filin alforec pad sevopa ej jesebfuh tap ma ajafihjoc pujawoso kuez zitu sebfal zialuti jool rudpi gogofiri da.');
    INSERT INTO property_reviews (
    guest_id, property_id, reservation_id, rating, message) 
    VALUES (
    891, 290, 1016559, 3, 'Hawapel pasale udmupnej co uzfos novuhig bilad dedgure vim renfef soumi suti bop.');
    INSERT INTO property_reviews (
    guest_id, property_id, reservation_id, rating, message) 
    VALUES (
    831, 195, 1011943, 3, 'Mu ozconas cuusoese kifefake cevletal gi fafsisar neza pafvum fepuje felsi tevcu nonu fa nod vukpoaj raw.');
    INSERT INTO property_reviews (
    guest_id, property_id, reservation_id, rating, message) 
    VALUES (
    613, 333, 1016292, 4, 'Beupuzo nuhe lac ko dafgacum mul padsuj sok hepfakih ba ne idu coffavze ugzuz hotmis.');
    INSERT INTO property_reviews (
    guest_id, property_id, reservation_id, rating, message) 
    VALUES (
    740, 658, 1019244, 5, 'Wuupiili ik rupe oci fawcur ihujufer toflevup akiho ra gan ofu wojukti pucid.');
    INSERT INTO property_reviews (
    guest_id, property_id, reservation_id, rating, message) 
    VALUES (
    302, 413, 1011557, 3, 'Hoptis helovna di nufit gihihi po hira zetaga ezfi ew danojo na fahlozhaz.');
    INSERT INTO property_reviews (
    guest_id, property_id, reservation_id, rating, message) 
    VALUES (
    697, 400, 1012993, 5, 'Taozu pachizic uleocuf ben kojvep jakot milnujwu paruli sunde maski ci oj mi eledif duper vah viffa.');
    INSERT INTO property_reviews (
    guest_id, property_id, reservation_id, rating, message) 
    VALUES (
    922, 524, 1013356, 5, 'Wod inkit jiuwi pejrozco mutsiub gikjansa zadusi rezur ad vaerowa vewlu hur gudesa lapima micsim mebrine vo dun.');
    INSERT INTO property_reviews (
    guest_id, property_id, reservation_id, rating, message) 
    VALUES (
    662, 947, 1010277, 4, 'Ishi ada juvecape epopo uvbirtuf uta fa zizape rap ejjip ted duzub ecaco.');
    INSERT INTO property_reviews (
    guest_id, property_id, reservation_id, rating, message) 
    VALUES (
    918, 221, 1016470, 5, 'Cu ipu detnov me otlossop zaorutok ezcegok ra ohagpu tawaffak cos vejsun liz nibpad tosju coka.');
    INSERT INTO property_reviews (
    guest_id, property_id, reservation_id, rating, message) 
    VALUES (
    316, 620, 1011909, 3, 'Catzizel el teaji me la agmihe advabfo fouzdo rodhim abe imodato ursoheb nugki zilec tos rodfoco nejwaow nihgutva.');
    INSERT INTO property_reviews (
    guest_id, property_id, reservation_id, rating, message) 
    VALUES (
    916, 145, 1014414, 3, 'Bemo kokzek bad bib nig dog ocaeta atuba dize lecha zud zaasa.');
    INSERT INTO property_reviews (
    guest_id, property_id, reservation_id, rating, message) 
    VALUES (
    939, 604, 1019094, 3, 'Mecagba ruspalti no jojcomho vel mi ca hagen nicimeuj uziroj solob ronhicuma datug mivfoku lal.');
    INSERT INTO property_reviews (
    guest_id, property_id, reservation_id, rating, message) 
    VALUES (
    474, 986, 1014270, 4, 'Samid jogmakjud so kifteb fecu vi vacugaat pila ofcivo mahgumed nototet kilcaim mecol ze.');
    INSERT INTO property_reviews (
    guest_id, property_id, reservation_id, rating, message) 
    VALUES (
    177, 538, 1013613, 3, 'Novidwub ciha mi ba caspa obaluvfib ri rimkitze jileb ar zugzuco fa ome.');
    INSERT INTO property_reviews (
    guest_id, property_id, reservation_id, rating, message) 
    VALUES (
    527, 410, 1011864, 5, 'Oco kaf penifi hijnufjad rewjugsil ukicaihi zostotuvo labhiiwe linak jifjog gutecav sijuta jolaec ahatud.');
    INSERT INTO property_reviews (
    guest_id, property_id, reservation_id, rating, message) 
    VALUES (
